import re

def string_expansion(s: str) -> str:
    if not s:
        return ''

    result = []
    multiplier = 1

    for char, num in re.findall(r'([a-zA-Z])(\d*)', s):
        if num:
            multiplier = int(num)
        result.append(char * multiplier)

    return ''.join(result)
